/// The icon an app name (Icon.svelte's names) stands for; unknown names draw the grid, as there.
pub fn by_name(name: &str) -> &'static Icon {
    match name {
        "home" => &HOME,
        "compass" => &COMPASS,
        "library" => &LIBRARY,
        "settings" => &SETTINGS,
        "plus" => &PLUS,
        "play" => &PLAY,
        "stop" => &STOP,
        "trash" => &TRASH,
        "cube" => &CUBE,
        "folder" => &FOLDER,
        "edit" => &EDIT,
        "user" => &USER,
        "search" => &SEARCH,
        "clock" => &CLOCK,
        "package" => &PACKAGE,
        "shuffle" => &SHUFFLE,
        "sparkles" => &SPARKLES,
        "expand" => &EXPAND,
        "refresh" => &REFRESH,
        "check" => &CHECK,
        "copy" => &COPY,
        "share" => &SHARE,
        "upload" => &UPLOAD,
        "download" => &DOWNLOAD,
        "users" => &USERS,
        "video" => &VIDEO,
        "globe" => &GLOBE,
        "trophy" => &TROPHY,
        "star" => &STAR,
        "heart" => &HEART,
        "moon" => &MOON,
        "fire" => &FIRE,
        "flag" => &FLAG,
        "crown" => &CROWN,
        "bolt" => &BOLT,
        "trending" => &TRENDING,
        "book" => &BOOK,
        "chevron-left" => &CHEVRON_LEFT,
        "chevron-right" => &CHEVRON_RIGHT,
        "chevron-down" => &CHEVRON_DOWN,
        "chevron-up" => &CHEVRON_UP,
        "filter" => &FILTER,
        "close" => &CLOSE,
        "grid" => &GRID,
        "list" => &LIST,
        _ => &GRID,
    }
}
